"""Generate discoverable API metadata from the trusted registry and config schema."""

import argparse
import json
from pathlib import Path

from ta_config import IndexConfig
from ta_config.core.registry import REGISTRY


def artifacts() -> dict[str, str]:
    rows = [
        "# Indicator registry reference",
        "",
        "Generated by scripts/generate_reference.py; do not edit by hand.",
        "",
        "| Config category | Public implementation | Input references | Outputs |",
        "| --- | --- | --- | --- |",
    ]
    for category, spec in REGISTRY.items():
        rows.append(
            f"| {category} | {spec.implementation.__name__} | "
            f"{', '.join(spec.inputs)} | "
            f"{', '.join(spec.implementation.output_keys('name'))} |"
        )
    rows += [
        "",
        "See config.schema.json for parameter constraints, required fields and aliases.",
        "",
    ]
    return {
        "api.md": "\n".join(rows),
        "config.schema.json": json.dumps(IndexConfig.model_json_schema(), indent=2) + "\n",
    }


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    destination = Path(__file__).resolve().parents[1] / "docs"
    if not args.check:
        destination.mkdir(exist_ok=True)
    for name, text in artifacts().items():
        path = destination / name
        if args.check:
            assert path.read_text(encoding="utf-8") == text, f"Regenerate {path}"
        else:
            path.write_text(text, encoding="utf-8")


if __name__ == "__main__":
    main()
